{"command":"set +e
for cmd in './executable' './executable nosuch' './executable --bad' './executable build --bad' './executable completions bad' './executable init --ignore bad'; do echo "=== $cmd ==="; out=$(mktemp); err=$(mktemp); eval "$cmd" >$out 2>$err; rc=$?; echo "rc=$rc"; echo "--stdout--"; sed -n '1,80p' $out; echo "--stderr--"; sed -n '1,120p' $err; rm -f $out $err; done

td=$(mktemp -d); echo "=== init temp noninteractive ==="; ./executable init --title 'My Book' --ignore git --force "$td" >$td/out 2>$td/err; echo rc=$?; echo stdout; sed -n '1,120p' $td/out; echo stderr; cat $td/err; echo files; find "$td" -maxdepth 3 -type f -printf '%P\n' | sort; echo book.toml; cat "$td/book.toml"; echo summary; cat "$td/src/SUMMARY.md"; echo gitignore; cat "$td/.gitignore"; rm -rf "$td""}

{"command":"set +e
td=$(mktemp -d); ./executable init --force "$td" >/dev/null 2>/dev/null; echo '```rust
fn main() {}
```' >> "$td/src/chapter_1.md"; echo "=== test good ==="; ./executable test "$td" >/tmp/o 2>/tmp/e; echo rc=$?; echo stdout; cat /tmp/o; echo stderr; sed -n '1,160p' /tmp/e; echo "=== test missing ==="; mt=$(mktemp -d); ./executable test "$mt" >/tmp/o 2>/tmp/e; echo rc=$?; echo stdout; cat /tmp/o; echo stderr; sed -n '1,80p' /tmp/e; rm -rf "$td" "$mt" /tmp/o /tmp/e
# Briefly start watch/serve under timeout to capture initial behavior
td=$(mktemp -d); ./executable init --force "$td" >/dev/null 2>/dev/null; echo "=== watch timeout ==="; timeout 2 ./executable watch "$td" >/tmp/o 2>/tmp/e; echo rc=$?; echo stdout; cat /tmp/o; echo stderr; sed -n '1,160p' /tmp/e; echo "=== serve timeout ==="; timeout 2 ./executable serve -p 39999 "$td" >/tmp/o 2>/tmp/e; echo rc=$?; echo stdout; sed -n '1,80p' /tmp/o; echo stderr; sed -n '1,180p' /tmp/e; rm -rf "$td" /tmp/o /tmp/e"}
